static const uint32_t uvl_glyph_count = 105;

uint32_t uvl_glyph_row(uint32_t cp, uint32_t row) {
  uint32_t lo = 0, hi = uvl_glyph_count;
  if (row >= 7) return 0;
  while (lo < hi) {
    uint32_t mid = lo + (hi - lo) / 2;
    uint16_t c = uvl_glyph_codes[mid];
    if (c == cp) return uvl_glyph_rows[mid * 7u + row];
    if (c < cp) lo = mid + 1;
    else hi = mid;
  }
  return 0xFFFFFFFFu;
}
